root.addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;if(b.id==='cv-open-baseline'){var nb=document.querySelector('.cv-nav button[data-cvp="baseline"]');if(nb)nb.click();setTimeout(function(){var p=document.querySelector('.cv-panel[data-panel="baseline"]');if(p)p.scrollIntoView({behavior:'smooth',block:'start'})},0);return}if(b.dataset.cvp){document.querySelectorAll('.cv-nav button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.cv-panel').forEach(x=>x.classList.toggle('active',x.dataset.panel===b.dataset.cvp));if(b.dataset.cvp==='area')setTimeout(polyRun,0);if(b.dataset.cvlocal==='1')setTimeout(function(){$('cv-from').value='local';$('cv-to').value='utm';renderOp();var c=$('cv-local-calibration');if(c)c.scrollIntoView({behavior:'smooth',block:'start'})},0)}if(b.id==='cv-run')runSingle();if(b.id==='cv-swap'){var f=$('cv-from').value,t=$('cv-to').value;$('cv-from').value=t;$('cv-to').value=f;renderOp()}if(b.id==='cv-copy'){navigator.clipboard&&navigator.clipboard.writeText($('cv-single-result').dataset.copy||'')}if(b.id==='cv-fit')fit();if(b.id==='cv-unit-run')unitRun();if(b.id==='cv-unit-reverse'){var f=$('cv-unit-from').value;$('cv-unit-from').value=$('cv-unit-to').value;$('cv-unit-to').value=f;unitRun()}if(b.id==='cv-shape-run')shapeRun();if(b.id==='cv-poly-run')polyRun();if(b.id==='cv-poly-sort'){var p=parseLines($('cv-poly').value),cx=p.reduce((a,x)=>a+x.x,0)/p.length,cy=p.reduce((a,x)=>a+x.y,0)/p.length;p.sort((a,b)=>Math.atan2(a.y-cy,a.x-cx)-Math.atan2(b.y-cy,b.x-cx));$('cv-poly').value=p.map(x=>x.id+','+x.x+','+x.y).join('\n');polyRun()}if(b.id==='cv-poly-file-btn')$('cv-poly-file').click();if(b.id==='cv-use-paste'){try{pastedTable($('cv-batch-paste').value)}catch(ex){showErr('cv-batch-summary',ex)}}if(b.id==='cv-process')batchConvert();if(b.id==='cv-xlsx')exportXlsx();if(b.id==='cv-csv')exportCsv();if(b.id==='cv-template')template();if(b.id==='cv-bl-run')calculateBaseline();if(b.id==='cv-bl-clear')renderBaselineInputs();if(b.id==='cv-bl-copy')copyBaseline();if(b.id==='cv-bl-csv')csvBaseline();if(b.id==='cv-bl-history-clear')clearBaselineHistory();if(b.id==='cv-bl-history-csv')exportBaselineHistory();if(b.id==='cv-sf-run')smartScaleCalculate();if(b.id==='cv-sf-clear')smartScaleClear();if(b.id==='cv-hd-run')horizontalCalculate();if(b.id==='cv-hd-clear')horizontalClear();if(b.id==='cv-advanced-toggle'){var ad=$('cv-advanced'),show=ad.classList.contains('hidden');ad.classList.toggle('hidden',!show);b.textContent=show?'Hide Advanced settings':'Show Advanced settings'}if(b.id==='cv-map-save')saveMappingProfile();if(b.id==='cv-map-delete')deleteMappingProfile();if(b.id==='cv-local-profile-save')saveLocalProfile();if(b.id==='cv-local-profile-load')loadLocalProfile();if(b.id==='cv-local-profile-delete')deleteLocalProfile();if(b.id==='cv-exclude-outliers')excludeOutliers();if(b.id==='cv-control-template')download(new Blob(['Point ID,Local X,Local Y,UTM Easting,UTM Northing\r\nCP01,1000,1000,601234.500,3567890.200'],{type:'text/csv'}),'local-utm-control-template.csv')});
root.addEventListener('change',function(e){if(e.target.id==='cv-from'||e.target.id==='cv-to')renderOp();if(e.target.id==='cv-batch-from')renderBatchTo();if(e.target.id==='cv-batch-to')renderBatchUtm(true);if(e.target.id==='cv-bl-factor-mode')renderFactorFields();if(e.target.id==='cv-bl-factor-convention')previewFactor();if(e.target.id==='cv-bl-az-format')renderAzimuthFields();if(e.target.id==='cv-map-profile')applyMappingProfile(e.target.value);if(e.target.id.indexOf('cv-map-')===0||['cv-batch-zone','cv-batch-hem','cv-height-in','cv-height-out','cv-geoid-mode'].indexOf(e.target.id)>=0)updateConfirmSummary();if(e.target.id==='cv-hd-mode')horizontalModeRender();if(e.target.id==='cv-unit-type')setupUnits();if(e.target.id==='cv-shape')renderShape();if(e.target.id==='cv-file'&&e.target.files[0]){var sf=e.target.files[0];digestFile(sf).then(function(h){readFile(sf,function(headers,rows,name,sheet){loaded(headers,rows,name,sheet);fileState.sha256=h;$('cv-file-meta').textContent+=' · SHA-256 verified';updateConfirmSummary()})})};if(e.target.id==='cv-poly-file'&&e.target.files[0])polyFile(e.target.files[0])});
root.addEventListener('input',function(e){if(e.target&&/^cv-bl-(factor|k-|grid-factor|elev-factor)/.test(e.target.id))previewFactor();if(e.target&&/^cv-bl-(e1|n1|e2|n2|smart-true)$/.test(e.target.id)){clearTimeout(smartBaselineTimer);smartBaselineTimer=setTimeout(function(){var ids=['cv-bl-e1','cv-bl-n1','cv-bl-e2','cv-bl-n2'];if(ids.every(function(id){return $(id)&&$(id).value.trim()!==''}))calculateSmartBaseline()},220)}});
var drop=$('cv-drop');['dragenter','dragover'].forEach(x=>drop.addEventListener(x,e=>{e.preventDefault();drop.classList.add('drag')}));['dragleave','drop'].forEach(x=>drop.addEventListener(x,e=>{e.preventDefault();drop.classList.remove('drag')}));drop.addEventListener('drop',e=>{var f=e.dataTransfer.files[0];if(f)digestFile(f).then(function(h){readFile(f,function(headers,rows,name,sheet){loaded(headers,rows,name,sheet);fileState.sha256=h;$('cv-file-meta').textContent+=' · SHA-256 verified';updateConfirmSummary()})})});
/* Persist unfinished converter entries and settings. The converter UI is injected after the
   application's generic autosave scan, so it needs its own late-bound store. */
var CV_PREFS_KEY='qc_converter_ui_v258',cvPrefsTimer=null;
function readConverterPrefs(){try{return JSON.parse(localStorage.getItem(CV_PREFS_KEY)||'{}')}catch(e){return{}}}
function applyConverterPrefs(only){var s=readConverterPrefs();Object.keys(s).forEach(function(id){if(only&&only.indexOf(id)<0)return;var el=$(id),rec=s[id];if(!el||!rec||el.type==='file')return;if((el.type==='checkbox'||el.type==='radio'))el.checked=!!rec.checked;else if(el.tagName==='SELECT'){if(Array.from(el.options).some(function(o){return o.value===String(rec.value)}))el.value=String(rec.value)}else el.value=rec.value==null?'':String(rec.value)})}
function saveConverterPrefs(){var s={};root.querySelectorAll('input[id^="cv-"],textarea[id^="cv-"],select[id^="cv-"]').forEach(function(el){if(el.type==='file'||el.disabled||el.readOnly)return;s[el.id]=(el.type==='checkbox'||el.type==='radio')?{checked:el.checked}:{value:el.value}});try{localStorage.setItem(CV_PREFS_KEY,JSON.stringify(s))}catch(e){}}
function queueConverterPrefs(){clearTimeout(cvPrefsTimer);cvPrefsTimer=setTimeout(saveConverterPrefs,180)}
root.addEventListener('input',queueConverterPrefs);root.addEventListener('change',queueConverterPrefs);
applyConverterPrefs(['cv-from','cv-to','cv-batch-from','cv-batch-to']);
renderBaselineInputs();renderBaselineHistory();engineHealth=runEngineSelfTests();var es=$('cv-engine-status');es.textContent=engineHealth.pass?'Engine self-test PASS':'Engine self-test FAILED';es.className='cv-badge '+(engineHealth.pass?'cv-ready':'cv-status-bad');renderOp();loadSavedH();renderLocalProfiles();renderMappingProfiles();renderBatchTo();horizontalModeRender();setupUnits();renderShape();polyRun();
applyConverterPrefs();
