renderOp();renderBatchTo();applyConverterPrefs();renderBatchUtm(false);updateConfirmSummary();
function converterLanguageOptions(){var arabic=document.documentElement.dir==='rtl';function label(id,value,en,ar){var e=$(id);if(!e)return;var o=Array.from(e.options).find(function(x){return x.value===value});if(o)o.textContent=arabic?ar:en}label('cv-out-hem','N','North (N)','شمالي (N)');label('cv-out-hem','S','South (S)','جنوبي (S)');label('cv-control-hem','N','North (N)','شمالي (N)');label('cv-control-hem','S','South (S)','جنوبي (S)');label('cv-batch-from','geo','Latitude / Longitude','خط العرض / خط الطول');label('cv-batch-from','local','Local X / Y','إحداثيات محلية X / Y');label('cv-batch-zone','','Use Zone column from file','استخدم عمود Zone من الملف');label('cv-batch-zone','auto','Automatic from Longitude','تلقائي من خط الطول');label('cv-batch-hem','','From file / automatic when valid','من الملف / تلقائي عند الإمكان');label('cv-batch-hem','N','North (N)','شمالي (N)');label('cv-batch-hem','S','South (S)','جنوبي (S)')}
converterLanguageOptions();var cvLastDir=document.documentElement.dir;new MutationObserver(function(){if(document.documentElement.dir!==cvLastDir){cvLastDir=document.documentElement.dir;converterLanguageOptions()}}).observe(document.documentElement,{attributes:true,attributeFilter:['dir']});
